import * as jsoncommon from './../../../jsoncommon';

/**
 * Ageable (minecraft:ageable)
 * Adds a timer for the entity to grow up. It can be accelerated by
 * giving the entity the items it likes as defined by 
 * feed_items.
 */
export default interface MinecraftAgeable {

  /**
   * @remarks
   * List of items that are dropped when an entity grows up
   */
  drop_items?: string[];

  /**
   * @remarks
   * Length of time before an entity grows up (-1 to always stay a
   * baby)
   * 
   * Sample Values:
   * Chicken: 1200
   *
   *
   */
  duration?: number;

  /**
   * @remarks
   * List of items that can be fed to the entity. Includes 'item' for
   * the item name, 'growth' to define how much time it grows up by,
   * and 'result_item' that defines what item the feed item will
   * transform to upon successful interaction (Format: 
   * itemName:auxValue).
   * 
   * Sample Values:
   * Chicken: ["wheat_seeds","beetroot_seeds","melon_seeds","pumpkin_seeds","pitcher_pod","torchflower_seeds"]
   *
   * Cow: "wheat"
   *
   * Dolphin: ["fish","salmon"]
   *
   */
  feed_items?: string[];

  /**
   * @remarks
   * List of items that can be fed to an entity to age them up
   */
  feedItems?: string[];

  /**
   * @remarks
   * Event to fire when an entity grows up
   * 
   * Sample Values:
   * Chicken: {"event":"minecraft:ageable_grow_up","target":"self"}
   *
   *
   * Dolphin: {"event":"ageable_grow_up","target":"self"}
   *
   */
  grow_up?: jsoncommon.MinecraftEventTrigger;

  /**
   * @remarks
   * List of conditions to meet so that the entity can be fed.
   */
  interact_filters?: jsoncommon.MinecraftFilter;

}